import{_ as o,o as t,c as s,a0 as a}from"./chunks/framework.DQOulFGV.js";const m=JSON.parse('{"title":"10. Build Plan — Achievable Goal & Sequenced Work","description":"","frontmatter":{},"headers":[],"relativePath":"10-build-plan.md","filePath":"10-build-plan.md"}'),d={name:"10-build-plan.md"};function i(c,e,n,r,l,p){return t(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="_10-build-plan-—-achievable-goal-sequenced-work" tabindex="-1">10. Build Plan — Achievable Goal &amp; Sequenced Work <a class="header-anchor" href="#_10-build-plan-—-achievable-goal-sequenced-work" aria-label="Permalink to &quot;10. Build Plan — Achievable Goal &amp; Sequenced Work&quot;">​</a></h1><blockquote><p>Status: <strong>Phases 1–3 are built and green; Phase 4 release scaffolding is in-repo (publishing credential-blocked).</strong> This document states the achievable goal, what already exists (verified by tests, not aspiration), what remains, and the exact sequence to reach a shippable v0.1.</p></blockquote><h2 id="_10-1-the-achievable-goal" tabindex="-1">10.1 The achievable goal <a class="header-anchor" href="#_10-1-the-achievable-goal" aria-label="Permalink to &quot;10.1 The achievable goal&quot;">​</a></h2><p><strong>Goal (v0.1):</strong> a local-first, deterministic, read-only MCP server + CLI that statically audits TypeScript test suites for tautological assertions and mock-contract drift, with <strong>zero false positives on the reference healthy suite</strong> and <strong>every finding under 100 tokens</strong>, runnable by <code>npx momus</code> and connectable as <code>momus-mcp</code> by any MCP client.</p><p>This goal is <strong>already met in the working tree</strong> — verified by 207 passing tests, a clean self-audit, and end-to-end CLI + MCP round-trips.</p><p><strong>Originally out of v0.1 scope, now shipped</strong> (kept here for history; everything below is done except registry publishing):</p><ul><li>✅ PHP support (Phase 2 — <code>@momus/parser-php</code> + engine integration)</li><li>✅ git-diff scoping + DRIFT-006 (Phase 3)</li><li>✅ CI GitHub Action + release-please release scaffolding (Phase 4; npm/MCP publishing still credential-blocked)</li><li>✅ <code>better-sqlite3</code> IR cache, chokidar file watcher, Streamable HTTP transport</li></ul><h2 id="_10-2-what-is-built-and-verified-do-not-rebuild" tabindex="-1">10.2 What is built and verified (do not rebuild) <a class="header-anchor" href="#_10-2-what-is-built-and-verified-do-not-rebuild" aria-label="Permalink to &quot;10.2 What is built and verified (do not rebuild)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Where</th><th>Verification</th></tr></thead><tbody><tr><td>Monorepo (npm workspaces)</td><td>root <code>package.json</code>, <code>tsconfig.base.json</code>, <code>vitest.config.ts</code></td><td><code>npm ci</code> + <code>npm test</code> + <code>npm run typecheck</code> green</td></tr><tr><td><code>@momus/core</code> — IR, config (JSONC), discovery, built-in glob, suppression, token budget, <code>SymbolIndex</code>, 14 rule classes, markdown/JSON formatters</td><td><code>packages/core/src/</code></td><td>60 unit tests</td></tr><tr><td><code>@momus/parser-typescript</code> — custom-host program (parent pointers, F5), symbols/signatures, mock detection (vi.mock / vi.fn / vi.spyOn / vi.mocked / object-literal / proxy / automock helpers), dataflow provenance (const-aware, F5/F6), comments with trailing detection</td><td><code>packages/parser-typescript/src/</code></td><td>33 unit tests + fixture gallery</td></tr><tr><td><code>@momus/parser-php</code> — <code>php-parser</code> plugin, typed symbols, PHPUnit/Mockery/Pest mock chains, configured values, <code>use</code> aliases, Composer PSR-4 + classmap resolution, PHP assertions</td><td><code>packages/parser-php/src/</code></td><td>7 integration tests + fixture gallery</td></tr><tr><td><code>@momus/mcp-server</code> — 5 tools (audit_test_fidelity, detect_tautological_assertions, verify_mock_drift, synthesize_mock_contract, list_rules), annotations + structuredContent, no stdout writes</td><td><code>packages/server/src/</code></td><td>10 integration tests (in-memory client round-trip, including PHP language selection)</td></tr><tr><td><code>@momus/cli</code> — audit / drift / contract / rules / serve / init / doctor, honest exit codes (pre-truncation)</td><td><code>packages/cli/src/</code></td><td>golden audit tests + smoke</td></tr><tr><td>Self-audit gate</td><td><code>.momusrc</code> + <code>npm run audit-self</code></td><td>clean on 30 repo files</td></tr><tr><td>CI</td><td><code>.github/workflows/ci.yml</code></td><td>typecheck + test + self-audit + fixture-smoke</td></tr></tbody></table><p><strong>Confirmed during the build (spec deltas already applied):</strong> npm workspaces over pnpm; <code>core</code> has zero runtime deps (built-in glob replaced picomatch); no parameter properties in source (Node strip-only mode — a <code>CompositeParser</code> regression crashed the bin and is now covered by a bin-symlink regression test); TAUT-003/TAUT-006 and invocation-site analysis are <code>let</code>-mutation and helper-call aware (fixed two false positives found by the self-audit).</p><h2 id="_10-3-sequenced-work-plan" tabindex="-1">10.3 Sequenced work plan <a class="header-anchor" href="#_10-3-sequenced-work-plan" aria-label="Permalink to &quot;10.3 Sequenced work plan&quot;">​</a></h2><h3 id="step-1-—-ship-v0-1-small-days-·-done" tabindex="-1">Step 1 — Ship v0.1 (small, days) · <code>done</code> <a class="header-anchor" href="#step-1-—-ship-v0-1-small-days-·-done" aria-label="Permalink to &quot;Step 1 — Ship v0.1 (small, days) · `done`&quot;">​</a></h3><ol><li>✅ <code>README.md</code> at repo root: quickstart (<code>npx momus audit .</code>), MCP client config snippet (Claude Desktop / Cursor / generic), links into <code>docs/</code>.</li><li>✅ <code>.gitignore</code> audit + <code>experiments/</code> decision: the E1–E8 spikes are <strong>kept for reference</strong> (documented in <code>docs/09-validation-report.md</code>); <code>experiments/node_modules/</code> is gitignored and <code>experiments/**</code> is excluded from self-audit via <code>.momusrc</code> ignorePatterns.</li><li>✅ <code>npm</code> bin links: <code>bin</code> + <code>files</code> fields in <code>packages/cli/package.json</code>; <code>npx momus</code> resolves through the workspace bin symlink (regression-tested).</li><li>✅ Publish dry-run (<code>npm pack --dry-run</code> in each package) clean. <strong>Acceptance:</strong> fresh clone → <code>npm ci &amp;&amp; npm test &amp;&amp; npm run audit-self</code> → green; <code>npx momus audit</code> on a real TS repo reports findings; <code>momus-mcp</code> connects to a client.</li></ol><h3 id="step-2-—-harden-the-engine-this-is-where-the-value-lives-·-done" tabindex="-1">Step 2 — Harden the engine (this is where the value lives) · <code>done</code> <a class="header-anchor" href="#step-2-—-harden-the-engine-this-is-where-the-value-lives-·-done" aria-label="Permalink to &quot;Step 2 — Harden the engine (this is where the value lives) · `done`&quot;">​</a></h3><ol><li>✅ <strong>BeforeEach/BeforeAll scope support</strong>: module-level and nested <code>describe</code> hooks now contribute configurations only to their applicable test functions, with lifecycle ordering and scope-isolation fixtures.</li><li>✅ <strong>More mock patterns</strong>: assigned <code>vi.fn()</code>/<code>jest.fn()</code> values, later <code>mockImplementation</code> configs, and Proxy doubles with mock-returning <code>get</code> handlers are collected; <code>jest.mock</code> factories, Proxy doubles, and module automock helpers have key/dynamic-handler extraction. The ambiguous TS <code>partialMock</code> helper stays deferred (no concrete convention exists; the named partial-mock form is PHP <code>createPartialMock</code>).</li><li>✅ <strong>DRIFT-002 (signature arity, first slice)</strong>: object-literal doubles extract required arity from <code>vi.fn((a, b) =&gt; ...)</code>, <code>jest.fn</code> implementations, and <code>spyOn(...).mockImplementation</code> callbacks. Conservative parameter-type compatibility and unknown-type escape hatches are covered; richer structural generic variance remains follow-up hardening.</li><li>✅ <strong>Loose name-based resolution fallback</strong>: syntax-only mode now preserves syntactic target names and enriches them through <code>SymbolIndex.resolveByName</code>; a no-<code>tsconfig.json</code> planted and healthy arity fixture proves the end-to-end path. <strong>Acceptance:</strong> each item has a planted-violation fixture and a healthy twin; self-audit stays clean.</li></ol><h3 id="step-3-—-phase-2-php-·-complete" tabindex="-1">Step 3 — Phase 2: PHP · <code>complete</code> <a class="header-anchor" href="#step-3-—-phase-2-php-·-complete" aria-label="Permalink to &quot;Step 3 — Phase 2: PHP · `complete`&quot;">​</a></h3><ol><li>✅ Spike and initial integration: E6 passes, and <code>packages/parser-php</code> now emits typed symbols, PHPUnit <code>createMock</code>/<code>method</code>/<code>willReturn</code> chains, and assertions into the shared IR.</li><li>✅ Configured-mock provenance for TAUT-002, <code>use ... as ...</code> aliases, Mockery/Pest chains <strong>incl. closure-form</strong> (<code>Mockery::mock(&#39;F&#39;, fn($m) =&gt; $m-&gt;shouldReceive(...)-&gt;andReturn(...))</code>, both <code>function</code> and arrow forms, span-scoped param binding), Composer PSR-4 <strong>and classmap fallback</strong> resolution, and original-constructor DRIFT-004 (incl. optional-parameter defaults: an all-optional constructor double with 0 args stays quiet) are covered. PHP DRIFT-003 return-type assignability is wired in the rule (declared types + cross-file class resolution; planted void/class/array mismatches fire, healthy twins stay quiet).</li><li>✅ Extend <code>.momusrc</code> PHP language gating and CLI/server parser selection; direct CLI dispatch and MCP PHP report coverage are now included. Broader CLI report behavior remains. <strong>Acceptance:</strong> PHP fixture gallery green; <code>momus audit</code> on a PHPUnit repo finds <code>createMock(&#39;X&#39;)</code> with a stale member (DRIFT-001) and a <code>willReturn</code> that echoes (TAUT-002).</li><li>✅ PHPDoc <code>@return</code>/<code>@param</code> typing: when a method has no native type, the parser reads the docblock into the signature (scalars, <code>?T</code> nullables, <code>T[]</code>/<code>array&lt;K,V&gt;</code> arrays, generics, union types, FQCN short-name resolution). Planted docblock-typed DRIFT-003 mismatches fire and the healthy twin stays quiet. <code>synthesize_mock_contract</code> now emits <code>phpunit</code>/<code>pest</code> templates (<code>createMock</code>/<code>mock</code> + <code>method</code>/<code>shouldReceive</code> + <code>willReturn</code>/<code>andReturn</code> with type-derived placeholder values) for PHP production classes; PHP templates render in a <code>php</code> code fence.</li><li>✅ Anonymous-class doubles: <code>new class extends Foo { … }</code> in test files emits <code>MockIR{pattern:&#39;anonymous-class&#39;}</code> targeting the parent (resolved through <code>use</code> aliases and FQCN short-names) with the override methods as <code>StubbedMemberIR</code> members. DRIFT-001 flags a planted stale override while the healthy override stays quiet.</li><li>✅ <code>momus doctor</code> PHP-readiness: reports the <code>languages.php</code> gate, <code>php-parser</code> availability, <code>composer.json</code> presence, and a bounded <code>.php</code> file count, summarizing as <code>off</code> / <code>ready</code> / <code>enabled (loose)</code>. Unit tests cover each branch.</li><li>✅ <code>getMockForAbstractClass</code> doubles: <code>$this-&gt;getMockForAbstractClass(AbstractFoo::class)</code> is now a distinct <code>MockIR{pattern:&#39;getMockForAbstractClass&#39;}</code> targeting the abstract class, with chained <code>method()</code>/<code>willReturn()</code> configs collected as stubbed members. A planted stale abstract member fires DRIFT-001 and the healthy abstract member stays quiet.</li><li>✅ PHP mock bindings are function-scoped: <code>byBinding</code> keys are now <code>scope:name</code> (enclosing class-method start line, 0 for top-level), so two test fns that reuse the same <code>$mock</code> variable no longer collide. The <code>AbstractMockTest</code> fixture reuses <code>$mock</code> across both fns to pin the behavior. Same-variable reassignment within one method is handled in item 10.</li><li>✅ PHP setUp/property mocks: <code>$this-&gt;prop = $this-&gt;createMock(Foo::class)</code> (the classic <code>setUp</code> assignment) is now captured — <code>assignmentBindingName</code> maps the LHS to a <code>this:prop</code> binding and <code>bindingName</code> resolves <code>$this-&gt;prop-&gt;method(...)</code> configs / assertion operands back to it. Property bindings are class-scoped (visible across the class&#39;s test methods). <code>SetUpMockTest</code> plants a stale <code>deleteById</code> (DRIFT-001), a <code>findById</code> echo (TAUT-002 + DRIFT-003), and a healthy <code>save</code> control.</li><li>✅ PHP same-variable reassignment: <code>recordBinding</code> stores assignments per <code>scope:name</code> key in line order, and <code>nearestBinding</code> resolves configs/assertion operands to the latest assignment at or before their line — so reassigning <code>$mock</code> within one method no longer shadows the earlier mock. <code>ReassignTest</code> reassigns <code>$mock</code> and pins <code>[[&#39;save&#39;], [&#39;findById&#39;]]</code>.</li></ol><h3 id="step-4-—-phase-3-git-diff-scoping-hooks-·-complete" tabindex="-1">Step 4 — Phase 3: git-diff scoping + hooks · <code>complete</code> <a class="header-anchor" href="#step-4-—-phase-3-git-diff-scoping-hooks-·-complete" aria-label="Permalink to &quot;Step 4 — Phase 3: git-diff scoping + hooks · `complete`&quot;">​</a></h3><ol><li>✅ <code>git diff --name-status</code> + <code>--find-renames</code> plumbing (<code>gitChangedPaths</code>, incl. untracked files and rename pairs) → <code>DiffScope</code>; DRIFT-006 (stale-mock) fires when the target changed but the mock file did not. Drift rules are diff-filtered: in git-diff mode only mocks whose target changed are re-checked.</li><li>✅ <code>momus precommit</code> (drift-only vs <code>--base</code>, default HEAD) and <code>momus audit|drift --git-diff --base REF</code>; the MCP <code>verify_mock_drift</code> tool wires <code>scope: git-diff</code> with <code>baseRef</code> (git errors surface as tool errors). <strong>Acceptance:</strong> on a repo where a production member was renamed, <code>precommit</code> flags the stale mock (DRIFT-006 + DRIFT-001) and exits 1; the healthy twin (test updated alongside) exits 0 — covered end-to-end by a git-repo fixture test.</li><li>✅ <code>momus hook</code> pre-commit installer: <code>hook --install</code>/<code>--uninstall</code> writes/removes <code>.git/hooks/pre-commit</code> (marker-guarded so foreign hooks are never removed, <code>--yes</code>-gated per §1.5, executable); <code>hook</code> (no flags) runs the staged-files drift gate via <code>gitStagedPaths</code> (index-only vs HEAD) and exits 1 on error findings. End-to-end: a staged production rename blocks the gate (DRIFT-006 + DRIFT-001) and the staged test update clears it.</li><li>✅ <code>momus serve --transport http [--port N]</code>: Streamable HTTP transport (<code>serveHttp</code> in <code>@momus/mcp-server</code>; SDK stateful per-session transports with stateless tools), end-to-end round-trip via <code>StreamableHTTPClientTransport</code> (tools/list + <code>verify_mock_drift</code>).</li><li>✅ <code>momus annotate [paths...] [--git-diff --base REF]</code>: machine-readable JSONL (one JSON object per issue — workspace-relative file/line/column, rule/severity/message, deterministic key order) for editor plugins; exits 1 on error findings.</li><li>✅ <code>momus audit --fix</code> mechanism: dry-run unified diff by default, <code>--yes</code> applies span-based fixes, refused in CI without <code>--yes</code> (§1.5). <code>collectFixable</code>/<code>applyFixes</code>/<code>unifiedDiff</code> are unit-tested. DRIFT-001 now emits a real rename fix (unique near-match within edit distance 2, quoted per stub api) and stub spans are narrowed to the name token; a planted stale spy is dry-run diffed, applied with <code>--yes</code>, and re-audits clean. TAUT-001/002/003 are semantic tautologies (any rewrite invents the asserted value) so they intentionally stay descriptive-only — a documented decision (§3.6), pinned by rule tests, not a gap.</li><li>✅ <code>momus serve --watch</code> (chokidar file-watching): <code>watchWorkspace(root)</code> in <code>@momus/mcp-server</code> watches TS/JS/PHP sources (ignoring node_modules/.git/dist/vendor/coverage) and calls <code>invalidateProgramCache()</code> (parser-typescript) on add/change/unlink, so watch-mode audits reflect on-disk edits without a restart. <code>invalidateProgramCache</code> + <code>watchWorkspace</code> are unit/integration tested.</li></ol><h3 id="step-5-—-phase-4-distribution-·-in-progress" tabindex="-1">Step 5 — Phase 4: distribution · <code>in progress</code> <a class="header-anchor" href="#step-5-—-phase-4-distribution-·-in-progress" aria-label="Permalink to &quot;Step 5 — Phase 4: distribution · `in progress`&quot;">​</a></h3><ol><li>✅ <code>packages/action/action.yml</code> composite action ships in-repo: diff-scoped audit (<code>audit . --git-diff --base</code>) + <code>momus annotate-pr</code> (GitHub Checks API annotations, dependency-free via built-in fetch; <code>fail-on</code> input; token/repo/sha from the Actions env).</li><li>✅ <code>release-please</code> + <code>release-please.yml</code> scaffolded in-repo (Knossos-style): <code>release-please-config.json</code> + <code>.release-please-manifest.json</code> pin a single lockstep version from <strong>0.0.1</strong>, bumping all five workspace <code>package.json</code>s via <code>json</code> extra-files; <code>pr-title.yml</code> gates Conventional Commit titles; on <code>release_created</code> the workflow runs the CI gate. npm publishing is <strong>manual-only</strong> (<code>scripts/publish.mjs</code>, dependency order) — not part of CI by project decision; run it deliberately when publishing is sanctioned. Registering <code>momus-mcp</code> in the MCP registry remains pending. <strong>Acceptance:</strong> a PR on any TS repo shows Momus annotations; <code>npx -y momus-mcp</code> serves.</li></ol><h2 id="_10-4-rules-of-engagement-hard-constraints-from-§1" tabindex="-1">10.4 Rules of engagement (hard constraints from §1) <a class="header-anchor" href="#_10-4-rules-of-engagement-hard-constraints-from-§1" aria-label="Permalink to &quot;10.4 Rules of engagement (hard constraints from §1)&quot;">​</a></h2><ul><li>Read-only: no tool/command writes to the audited workspace.</li><li>Deterministic: byte-identical output for identical workspace (golden-tested).</li><li>&lt; 100 tokens per issue line (unit-tested via <code>assertTokenBudget</code>).</li><li>New language/pattern support ships <strong>only</strong> with a planted anti-pattern fixture + a healthy twin, both in the gallery, both asserted in CI.</li><li>Nothing unconfirmed ships as &quot;done&quot;: each Step above names its verification.</li></ul><h2 id="_10-5-risks-honest" tabindex="-1">10.5 Risks (honest) <a class="header-anchor" href="#_10-5-risks-honest" aria-label="Permalink to &quot;10.5 Risks (honest)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Risk</th><th>Mitigation</th></tr></thead><tbody><tr><td><code>ts.createProgram</code> cost on large repos (whole-workspace per audit)</td><td>Perf budgets §2.7; incremental program + IR cache are Phase 2 work, isolated behind <code>SymbolIndex</code></td></tr><tr><td><code>beforeEach</code>-configured mocks produce wrong scopes</td><td>✅ Step 2.1; fixtures pin the semantics</td></tr><tr><td>PHP chain-fidelity assumptions</td><td>Step 3.1 spike gates the whole phase</td></tr><tr><td>Node version skew (20 vs 22 vs 25 native TS)</td><td><code>engines: &gt;=20</code>; CI runs 22; no parameter properties in source</td></tr></tbody></table>',25)])])}const u=o(d,[["render",i]]);export{m as __pageData,u as default};
